import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class StreamPipelineExample {
    public static Map<String, List<String>> groupAndFilterUsers(List<User> users) {
        return users.stream()
                .filter(User::isActive) // Intermediate operation (lazy)
                .map(User::getDepartment) // Intermediate operation (lazy)
                .distinct() // Stateful intermediate operation
                .collect(Collectors.groupingBy(dept -> dept.substring(0, 1))); // Terminal operation (eager trigger)
    }
}
